SELECT t.TAG_ID AS tagId, t.TAG_NAME AS tagName, t.REMARK AS remark, t.CREATE_BY AS createBy, t.CREATE_TIME AS createTime, t.UPDATE_TIME AS updateTime, COUNT(r.ID) AS memberCount FROM PERSON_TAG t LEFT JOIN PERSON_TAG_REL r ON r.TAG_ID = t.TAG_ID
t.TAG_NAME LIKE CONCAT('%', #{keyword}, '%')
GROUP BY t.TAG_ID, t.TAG_NAME, t.REMARK, t.CREATE_BY, t.CREATE_TIME, t.UPDATE_TIME ORDER BY t.CREATE_TIME DESC, t.TAG_ID DESC LIMIT #{offset}, #{size}
